namespace OctoshiftCLI.Services;

/// <summary>
/// Safely tests an Azure DevOps pipeline migration to GitHub by rewiring the pipeline,
/// queueing a build, restoring the original ADO configuration, and monitoring the build result.
/// </summary>
public class PipelineTestService
{
    private readonly OctoLogger _log;
    private readonly AdoApi _adoApi;
    private readonly AdoPipelineTriggerService _pipelineTriggerService;

    // Interval used when polling the build for status updates.
    private readonly int _monitorDelayMilliseconds;

    public PipelineTestService(OctoLogger log, AdoApi adoApi, AdoPipelineTriggerService pipelineTriggerService)
        : this(log, adoApi, pipelineTriggerService, 10000)
    {
    }

    public PipelineTestService(OctoLogger log, AdoApi adoApi, AdoPipelineTriggerService pipelineTriggerService, int monitorDelayMilliseconds)
    {
        _log = log;
        _adoApi = adoApi;
        _pipelineTriggerService = pipelineTriggerService;
        _monitorDelayMilliseconds = monitorDelayMilliseconds;
    }

    public virtual async Task<PipelineTestResult> TestPipeline(PipelineTestArgs args)
    {
        if (args is null)
        {
            throw new ArgumentNullException(nameof(args));
        }

        var result = new PipelineTestResult
        {
            AdoOrg = args.AdoOrg,
            AdoTeamProject = args.AdoTeamProject,
            PipelineName = args.AdoPipeline,
            StartTime = DateTime.UtcNow,
        };

        // Resolve the pipeline id if it was not supplied.
        var pipelineId = args.PipelineId ?? await _adoApi.GetPipelineId(args.AdoOrg, args.AdoTeamProject, args.AdoPipeline);
        result.PipelineId = pipelineId;

        // Capture the original pipeline info so it can be restored afterwards.
        var originalDefinition = await _adoApi.GetPipelineDefinition(args.AdoOrg, args.AdoTeamProject, pipelineId);
        result.AdoRepoName = await _adoApi.GetPipelineRepositoryName(args.AdoOrg, args.AdoTeamProject, pipelineId);

        var (defaultBranch, clean, checkoutSubmodules, triggers) = await _adoApi.GetPipeline(args.AdoOrg, args.AdoTeamProject, pipelineId);

        // Rewire the pipeline to point at the GitHub repo.
        _log.LogInformation($"Rewiring pipeline '{args.AdoPipeline}' to GitHub repo {args.GithubOrg}/{args.GithubRepo}...");
        await _pipelineTriggerService.RewirePipelineToGitHub(
            args.AdoOrg,
            args.AdoTeamProject,
            pipelineId,
            defaultBranch,
            clean,
            checkoutSubmodules,
            args.GithubOrg,
            args.GithubRepo,
            args.ServiceConnectionId,
            triggers,
            args.TargetApiUrl);
        result.RewiredSuccessfully = true;

        // Queue a build against the rewired pipeline.
        _log.LogInformation("Queueing test build...");
        var (buildId, buildUrl) = await _adoApi.QueueBuild(args.AdoOrg, args.AdoTeamProject, pipelineId);
        result.BuildId = buildId;
        result.BuildUrl = buildUrl;

        // Restore the pipeline back to the original ADO repo. Never let a restore failure
        // propagate - record it on the result instead so the caller can react.
        try
        {
            _log.LogInformation("Restoring pipeline to original Azure DevOps repo...");
            await _pipelineTriggerService.RestorePipelineToAdoRepo(args.AdoOrg, args.AdoTeamProject, pipelineId, originalDefinition);
            result.RestoredSuccessfully = true;
        }
        catch (Exception ex)
        {
            result.RestoredSuccessfully = false;
            result.ErrorMessage = "Failed to restore: " + ex.Message;
            result.EndTime = DateTime.UtcNow;
            return result;
        }

        // Monitor the build until it completes or the timeout elapses.
        await MonitorBuild(args, buildId, result);

        result.EndTime = DateTime.UtcNow;
        return result;
    }

    private async Task MonitorBuild(PipelineTestArgs args, int buildId, PipelineTestResult result)
    {
        var timeout = TimeSpan.FromMinutes(args.MonitorTimeoutMinutes > 0 ? args.MonitorTimeoutMinutes : 30);
        var deadline = DateTime.UtcNow + timeout;

        while (true)
        {
            var (status, buildResult) = await _adoApi.GetBuildStatus(args.AdoOrg, args.AdoTeamProject, buildId);
            result.Status = status;
            result.Result = buildResult;

            if (result.IsCompleted)
            {
                break;
            }

            if (DateTime.UtcNow >= deadline)
            {
                _log.LogWarning($"Timed out after {timeout.TotalMinutes} minutes while monitoring build {buildId}.");
                break;
            }

            await Task.Delay(_monitorDelayMilliseconds);
        }
    }
}
